<?php
declare(strict_types=1);
use DigiForge\POD\{CutoutVisualQa,RasterArtworkCodec};
use PHPUnit\Framework\TestCase;
require_once __DIR__.'/../../includes/POD/RasterArtworkCodec.php';
if(is_file(__DIR__.'/../../includes/POD/CutoutVisualQa.php'))require_once __DIR__.'/../../includes/POD/CutoutVisualQa.php';
final class CutoutVisualQaTest extends TestCase {
 private function image(int $a=128):string {$p=str_repeat("\0",5*5*4);$p=substr_replace($p,"\x80\x40\x20".chr($a),48,4);return RasterArtworkCodec::encode(5,5,$p);}
 public function testMeasuredAlphaAndReferenceErrorNeverCertifyArtwork():void {self::assertTrue(class_exists(CutoutVisualQa::class),'QA implementation missing');$q=CutoutVisualQa::measure($this->image(),$this->image(255));self::assertSame(1,$q['soft_alpha_pixels']);self::assertSame(0,$q['boundary_pixels']);self::assertEqualsWithDelta(127/(255*25),$q['reference']['mean_absolute_alpha_error'],1e-12);self::assertSame('UNREVIEWED_COMPARISON',$q['reference']['state']);self::assertFalse($q['commercial_certified']);self::assertSame($q,CutoutVisualQa::measure($this->image(),$this->image(255)));}
 public function testMissingGroundTruthIsNotZeroError():void {self::assertTrue(class_exists(CutoutVisualQa::class),'QA implementation missing');$q=CutoutVisualQa::measure($this->image());self::assertSame('MISSING',$q['reference']['state']);self::assertNull($q['reference']['mean_absolute_alpha_error']);self::assertSame('OPERATOR_REVIEW_REQUIRED',$q['state']);}
 public function testClippedAndEmptyMasksAreCriticalFailures():void {self::assertTrue(class_exists(CutoutVisualQa::class),'QA implementation missing');$q=CutoutVisualQa::measure(RasterArtworkCodec::encode(2,2,str_repeat("\xff",16)));self::assertSame('CRITICAL_DEFECT',$q['state']);self::assertContains('boundary_clipping',$q['critical_defects']);self::assertContains('no_transparent_background',$q['critical_defects']);self::assertContains('empty_foreground',CutoutVisualQa::measure($this->image(0))['critical_defects']);}
 public function testPreviewsUseActualAlphaAndReferenceGeometryMustMatch():void {self::assertTrue(class_exists(CutoutVisualQa::class),'QA implementation missing');$p=CutoutVisualQa::previews($this->image());self::assertNotSame($p['light'],$p['dark']);self::assertSame(255,ord(RasterArtworkCodec::decode($p['light'])['rgba'][51]));$this->expectException(InvalidArgumentException::class);CutoutVisualQa::measure($this->image(),RasterArtworkCodec::encode(1,1,"\xff\xff\xff\xff"));}
 public function testSyntheticMultiSubjectReferenceHasExactZeroErrorAndTamperChangesEvidence():void {self::assertTrue(class_exists(CutoutVisualQa::class));$p=str_repeat("\0",7*7*4);foreach([8,24,40]as $pixel)$p=substr_replace($p,"\x80\x40\x20\xff",$pixel*4,4);$png=RasterArtworkCodec::encode(7,7,$p);$q=CutoutVisualQa::measure($png,$png);self::assertSame(3,$q['visible_pixels']);self::assertSame(1,$q['reference']['alpha_iou_128']);self::assertSame(0,$q['reference']['mean_absolute_alpha_error']);$p[8*4+3]="\x80";$changed=CutoutVisualQa::measure(RasterArtworkCodec::encode(7,7,$p));self::assertNotSame($q['artifact_sha256'],$changed['artifact_sha256']);self::assertFalse($q['commercial_certified']);}
 public function testCorruptPngCannotBecomeQaEvidence():void {self::assertTrue(class_exists(CutoutVisualQa::class));$this->expectException(InvalidArgumentException::class);CutoutVisualQa::measure($this->image().'tampered');}
 public function testDetailRegionsMeasureRealAlphaWithoutSemanticApproval():void {self::assertTrue(method_exists(CutoutVisualQa::class,'detailComparisons'),'Detail metric boundary missing');$regions=[['kind'=>'hair','x'=>1,'y'=>1,'width'=>3,'height'=>3]];$r=CutoutVisualQa::detailComparisons($this->image(),$this->image(255),$regions);self::assertEqualsWithDelta(127/(255*9),$r[0]['metrics']['reference']['mean_absolute_alpha_error'],1e-12);self::assertFalse($r[0]['metrics']['commercial_certified']);self::assertArrayNotHasKey('critical_defects',$r[0]['metrics']);$regions[0]['x']=4;$this->expectException(InvalidArgumentException::class);CutoutVisualQa::detailComparisons($this->image(),$this->image(255),$regions);}
}
